<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>第一章 教育与教育学</title>
<style>
  body {
    font-family: "Microsoft YaHei", "SimHei", sans-serif;
    font-size: 14px;
    color: #333;
    background-color: #fff;
    background-image: repeating-linear-gradient(to bottom, transparent, transparent 31px, #e8e8e8 31px, #e8e8e8 32px);
    line-height: 1.5;
    margin: 0;
    padding: 40px;
    overflow-x: auto;
  }

  .mindmap-container {
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    min-width: 1000px;
  }

  .header {
    align-self: center;
    margin-bottom: 40px;
  }

  .title-box {
    background-color: #f4b183;
    padding: 8px 25px;
    border-radius: 3px;
    font-weight: bold;
    font-size: 18px;
    border: 1px solid #e2935d;
    box-shadow: 1px 1px 3px rgba(0,0,0,0.1);
  }

  .tree-wrapper {
    display: flex;
    align-items: stretch;
  }

  .root-node {
    display: flex;
    align-items: center;
  }

  .root-text {
    background-color: #fff2cc;
    padding: 20px 10px;
    text-align: center;
    line-height: 1.3;
    border: 1px solid #d6b656;
    border-radius: 3px;
    font-weight: bold;
    font-size: 16px;
    box-shadow: 1px 1px 3px rgba(0,0,0,0.1);
  }

  .main-bracket-container {
    display: flex;
    align-items: center;
    margin: 0 15px;
  }

  .main-bracket {
    width: 20px;
    border-top: 2px solid #4472c4;
    border-bottom: 2px solid #4472c4;
    border-left: 2px solid #4472c4;
    align-self: stretch;
    position: relative;
    margin: 30px 0;
  }

  .main-bracket::before {
    content: '';
    position: absolute;
    left: -8px;
    top: 50%;
    transform: translateY(-50%);
    border-top: 6px solid transparent;
    border-bottom: 6px solid transparent;
    border-right: 6px solid #4472c4;
  }

  .level-nodes {
    display: flex;
    flex-direction: column;
    justify-content: space-around;
    padding: 10px 0;
  }

  /* Tree Layout CSS */
  .node-group {
    display: flex;
    position: relative;
    margin: 6px 0;
    align-items: flex-start; /* Default top align */
  }

  .node-content {
    white-space: nowrap;
    padding: 2px 0;
    position: relative;
    z-index: 1;
    background-color: rgba(255,255,255,0.8); /* Slight bg to cover lines if needed */
  }

  .node-children {
    display: flex;
    flex-direction: column;
    margin-left: 30px;
    position: relative;
  }

  /* Horizontal line entering a node */
  .node-children > .node-group::before {
    content: '';
    position: absolute;
    left: -30px;
    top: 12px;
    width: 30px;
    border-top: 1px solid #999;
  }

  /* Vertical line */
  .node-children > .node-group::after {
    content: '';
    position: absolute;
    left: -30px;
    top: 0;
    bottom: 0;
    border-left: 1px solid #999;
  }
  .node-children > .node-group:first-child::after {
    top: 12px;
  }
  .node-children > .node-group:last-child::after {
    bottom: auto;
    height: 12px;
  }

  /* Line from parent to vertical line */
  .node-group:not(.center-align) > .node-children::before {
    content: '';
    position: absolute;
    left: -30px;
    top: 12px;
    width: 30px;
    border-top: 1px solid #999;
  }

  /* Center Alignment Modifier */
  .node-group.center-align {
    align-items: center;
  }
  .node-group.center-align > .node-children > .node-group::before {
    top: 50%;
  }
  .node-group.center-align > .node-children > .node-group:first-child::after {
    top: 50%;
  }
  .node-group.center-align > .node-children > .node-group:last-child::after {
    bottom: 50%;
    height: auto;
  }
  .node-group.center-align > .node-children::before {
    content: '';
    position: absolute;
    left: -30px;
    top: 50%;
    width: 30px;
    border-top: 1px solid #999;
  }

  /* Specific Styles */
  .highlight-green {
    background-color: #e2efda;
    padding: 2px 8px;
    border-radius: 3px;
    font-weight: bold;
  }

  .dot {
    display: inline-block;
    width: 10px;
    height: 10px;
    border-radius: 50%;
    margin-right: 6px;
    vertical-align: middle;
    margin-top: -2px;
  }
  .dot-blue { background-color: #4472c4; }
  .dot-purple { background-color: #7030a0; }
  .dot-magenta { background-color: #d10074; }

  .text-red { 
    color: #c00000; 
  }

  .flex-row {
    display: flex;
    align-items: stretch;
  }

  .left-part {
    display: flex;
    align-items: center;
    padding-right: 10px;
  }

  .right-part {
    display: flex;
    flex-direction: column;
    justify-content: center;
  }

  .border-left {
    border-left: 1px solid #999;
    padding-left: 10px;
  }

  .indent {
    padding-left: 1.5em;
  }
</style>
</head>
